package cn.xi.cloudwidget;

import android.app.*;
import android.content.*;
import android.graphics.*;
import android.os.*;
import org.json.*;
import java.io.*;
import java.util.*;
import java.util.zip.*;

/** Isolated contexts keep empty-data and destructive-input tests away from existing cards. */
public class BackupChecks extends Instrumentation {
    Bundle args;Context target;StringBuilder report=new StringBuilder();int count;
    @Override public void onCreate(Bundle args){this.args=args;start();}
    void check(boolean value,String text){if(!value)throw new AssertionError(text);report.append("PASS ").append(text).append('\n');count++;}
    static class Isolated extends ContextWrapper {
        final String name="qa034-"+UUID.randomUUID();final File root;
        Isolated(Context c){super(c);root=c.getDir(name,0);}
        @Override public Context getApplicationContext(){return this;}
        @Override public File getFilesDir(){File f=new File(root,"files");f.mkdirs();return f;}
        @Override public File getCacheDir(){File f=new File(root,"cache");f.mkdirs();return f;}
        @Override public SharedPreferences getSharedPreferences(String n,int m){return getBaseContext().getSharedPreferences(name+"-"+n,m);}
    }
    byte[] art(Context c,String id)throws Exception{try(InputStream in=new AssetStore(c).get(id).open(c)){return Io.read(in);}}
    static byte[] zip(Map<String,byte[]> files)throws Exception{ByteArrayOutputStream output=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(output)){for(Map.Entry<String,byte[]> entry:files.entrySet()){zip.putNextEntry(new ZipEntry(entry.getKey()));zip.write(entry.getValue());zip.closeEntry();}}return output.toByteArray();}
    Map<String,byte[]> unzip(File file)throws Exception{Map<String,byte[]> values=new LinkedHashMap<>();try(ZipInputStream zip=new ZipInputStream(new FileInputStream(file))){ZipEntry e;while((e=zip.getNextEntry())!=null)values.put(e.getName(),Io.read(zip));}return values;}
    byte[] imageZip(String id,byte[] png)throws Exception{JSONObject manifest=new JSONObject().put("schema",1).put("id",id).put("name","备份测试素材包").put("author","isolated QA").put("version","1").put("assets",new JSONArray().put(new JSONObject().put("id","pet").put("name","本地素材").put("category","dog").put("file","pet.png")));Map<String,byte[]> files=new TreeMap<>();files.put("manifest.json",manifest.toString().getBytes("UTF-8"));files.put("pet.png",png);return zip(files);}
    String fixture(Context c)throws Exception{
        String packId="qa034-"+UUID.randomUUID();byte[] dog=art(c,"builtin:blue-books-dog"),flowers=art(c,"builtin:cream-flowers");AssetStore assets=new AssetStore(c);AssetStore.Pack pack=assets.prepareZip(new ByteArrayInputStream(imageZip(packId,dog)));assets.commit(pack);String single=assets.importPng(new ByteArrayInputStream(flowers)).ref;
        Backup.write(new File(c.getFilesDir(),"photos/subject.png"),dog);Backup.write(new File(c.getFilesDir(),"photos/background.png"),flowers);
        for(int n=0;n<4;n++){Card card=n==2?Card.mini():new Card();card.id="fixture-"+n;card.shape=n==1?1:n==2?2:0;card.type=n==1||n==2?1:n==3?4:3;card.font=4+n%3;card.title="今天，也要好好生活！";card.body="中文、数字 0123456789，长句换行与缺字回退：𠮷 ☁️";if(n==1){card.photo="subject.png";card.backgroundPhoto="background.png";card.bgMode=2;}card.addSticker(n==0?"pack:"+packId+"@1:pet":n==2?single:"builtin:blue-sprig");card.toggle(0,java.time.LocalDate.of(2024,2,29));card.toggle(2,java.time.LocalDate.of(2025,1,1));new Store(c).save(card);}new Store(c).bind(90210,"fixture-0");c.getSharedPreferences("widget-geometry-v1",0).edit().putString("widget:90210","not-portable").commit();return packId;
    }
    String state(Context c)throws Exception{return new TreeMap<>(Backup.prefs(c).getAll()).toString();}
    String pixels(Context c,Card card){Bitmap image=Renderer.render(c,card,320,240,true);ByteArrayOutputStream out=new ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.PNG,100,out);image.recycle();return AssetStore.hash(out.toByteArray());}
    void rejected(Context c,Map<String,byte[]> files,String label)throws Exception{String before=state(c);boolean failed=false;try(Backup.Plan ignored=Backup.prepare(c,new ByteArrayInputStream(zip(files)))){}catch(Exception error){failed=true;}check(failed&&before.equals(state(c)),label+" rejects without changing saved data");}
    void updateInventory(Map<String,byte[]> files)throws Exception{JSONObject meta=new JSONObject(new String(files.get("backup.json"),"UTF-8"));JSONArray all=meta.getJSONArray("files");for(int n=0;n<all.length();n++){JSONObject entry=all.getJSONObject(n);byte[] b=files.get(entry.getString("path"));if(b!=null){entry.put("bytes",b.length);entry.put("sha256",AssetStore.hash(b));}}files.put("backup.json",meta.toString().getBytes("UTF-8"));}
    void tests()throws Exception{
        Isolated source=new Isolated(target);String packId=fixture(source);File archive=Backup.export(source);check(archive.isFile(),"complete export builds and validates a temporary ZIP");Map<String,byte[]> files=unzip(archive);String manifest=new String(files.get("backup.json"),"UTF-8");check(!manifest.contains("90210")&&!files.containsKey("cards-v1.xml")&&!files.containsKey("widget-geometry-v1.xml"),"export excludes widget bindings, geometry, preferences and secrets");check(files.keySet().stream().noneMatch(p->p.endsWith(".ttf")||p.endsWith(".otf")),"backup references built-in fonts instead of copying APK font binaries");
        Isolated empty=new Isolated(target);String before=state(empty);try(Backup.Plan plan=Backup.prepare(empty,new FileInputStream(archive))){check(plan.cards.length()==4&&plan.photos==2&&plan.packs==1&&plan.pngs==1,"preview reports all card, photo, pack and single-PNG counts");check(state(empty).equals(before)&&new AssetStore(empty).all().size()==34,"validation makes no visible card or library changes");}check(state(empty).equals(before),"cancelled prepared import leaves the isolated empty store intact");
        try(Backup.Plan plan=Backup.prepare(empty,new FileInputStream(archive))){check(Backup.apply(empty,plan,Backup.NONE)==4,"empty-data restore publishes every card");}
        Store restored=new Store(empty);check(restored.binding(90210).isEmpty()&&empty.getSharedPreferences("widget-geometry-v1",0).getAll().isEmpty(),"restore does not copy host IDs or measured geometry");for(int n=0;n<4;n++){Card a=new Store(source).get("fixture-"+n),b=restored.get(a.id);check(b!=null&&b.shape==a.shape&&b.font==a.font&&b.type==a.type,"card type, shape and font survive round trip "+n);check(Arrays.equals(a.itemIds,b.itemIds)&&a.history.toString().equals(b.history.toString()),"stable item IDs and complete dated history survive "+n);check(pixels(source,a).equals(pixels(empty,b)),"restored render matches source including all resource references "+n);}
        String after=state(empty);try(Backup.Plan again=Backup.prepare(empty,new FileInputStream(archive))){check(again.duplicate&&Backup.apply(empty,again,Backup.NONE)==0&&state(empty).equals(after),"repeated backup import is explicit and creates no duplicate cards");}
        File exportedAgain=Backup.export(empty);try(Backup.Plan again=Backup.prepare(new Isolated(target),new FileInputStream(exportedAgain))){check(again.cards.length()==4&&again.photos==2&&again.packs==1&&again.pngs==1,"restored data exports again as a complete reference closure");}
        Isolated merge=new Isolated(target);byte[] other=art(merge,"builtin:cream-flowers");AssetStore assets=new AssetStore(merge);AssetStore.Pack conflict=assets.prepareZip(new ByteArrayInputStream(imageZip(packId,other)));assets.commit(conflict);Card original=new Store(source).get("fixture-0");original.title="原卡不能覆盖";new Store(merge).save(original);new Store(merge).bind(12345,original.id);String originalRaw=Backup.prefs(merge).getString("card:"+original.id,null),oldPixels=pixels(merge,original);assets.importPng(new ByteArrayInputStream(other));
        try(Backup.Plan plan=Backup.prepare(merge,new FileInputStream(archive))){check(plan.conflicts==1,"merge preview counts card ID conflicts before confirmation");check(Backup.apply(merge,plan,Backup.NONE)==4,"merge adds four cards while preserving conflicting originals");}
        check(Backup.prefs(merge).getString("card:fixture-0","").equals(originalRaw)&&new Store(merge).binding(12345).equals("fixture-0")&&pixels(merge,original).equals(oldPixels),"merge preserves original card JSON, old asset pixels and desktop binding");Card copied=null;for(Card c:new Store(merge).all())if(!c.id.equals("fixture-0")&&c.type==3)copied=c;check(copied!=null&&Arrays.equals(copied.itemIds,new Store(source).get("fixture-0").itemIds)&&!copied.stickers.getJSONObject(0).getString("asset").equals(original.stickers.getJSONObject(0).getString("asset")),"conflicting pack gets a new reference while copied card retains item IDs");check(pixels(merge,copied).equals(pixels(source,new Store(source).get("fixture-0"))),"remapped conflicting pack renders the incoming artwork");check(new File(merge.getFilesDir(),"stickers").listFiles().length==1,"identical single PNGs deduplicate");
        Map<String,byte[]> bad=new LinkedHashMap<>(files);bad.put("../escape.png",other);rejected(merge,bad,"path traversal");bad=new LinkedHashMap<>(files);bad.remove("cards.json");rejected(merge,bad,"missing file");bad=new LinkedHashMap<>(files);bad.put("cards.json","[]".getBytes("UTF-8"));rejected(merge,bad,"hash mismatch");bad=new LinkedHashMap<>(files);JSONObject meta=new JSONObject(manifest);meta.put("format",99);bad.put("backup.json",meta.toString().getBytes("UTF-8"));rejected(merge,bad,"future backup format");bad=new LinkedHashMap<>(files);JSONArray cards=new JSONArray(new String(bad.get("cards.json"),"UTF-8"));cards.getJSONObject(0).getJSONArray("stickers").getJSONObject(0).put("asset","png:"+String.join("",Collections.nCopies(64,"0")));bad.put("cards.json",cards.toString().getBytes("UTF-8"));updateInventory(bad);rejected(merge,bad,"broken reference closure");bad=new LinkedHashMap<>(files);meta=new JSONObject(manifest);meta.getJSONArray("fonts").getJSONObject(0).put("sha256","unknown-font-version");bad.put("backup.json",meta.toString().getBytes("UTF-8"));rejected(merge,bad,"missing built-in font version");bad=new LinkedHashMap<>(files);meta=new JSONObject(manifest);meta.getJSONArray("builtinAssets").getJSONObject(0).put("ref","builtin:not-installed");bad.put("backup.json",meta.toString().getBytes("UTF-8"));rejected(merge,bad,"missing built-in artwork");
        byte[] truncated=Arrays.copyOf(zip(files),90);boolean failed=false;try(Backup.Plan ignored=Backup.prepare(merge,new ByteArrayInputStream(truncated))){}catch(Exception error){failed=true;}check(failed,"truncated ZIP is rejected");
        for(String phase:new String[]{"before-journal","after-file","before-publish"}){Isolated failedStore=new Isolated(target);Card keep=new Card();keep.id="keep";new Store(failedStore).save(keep);new Store(failedStore).bind(7,"keep");String saved=state(failedStore);boolean thrown=false;try(Backup.Plan plan=Backup.prepare(failedStore,new FileInputStream(archive))){try{Backup.apply(failedStore,plan,at->{if(at.equals(phase))throw new IOException("injected storage failure");});}catch(IOException error){thrown=true;}}check(thrown&&saved.equals(state(failedStore))&&new AssetStore(failedStore).all().size()==34,"write failure rolls back files and card publication at "+phase);File retried=Backup.export(failedStore);check(retried.isFile(),"export still works after rolled-back file writes "+phase);Backup.remove(retried.getParentFile());}
        for(String phase:new String[]{"after-file","before-publish","after-publish"}){Isolated crash=new Isolated(target);Backup.Plan plan=Backup.prepare(crash,new FileInputStream(archive));try{Backup.apply(crash,plan,at->{if(at.equals(phase))throw new SimulatedCrash();});}catch(SimulatedCrash expected){}check(Backup.journal(crash).getBaseFile().exists(),"interruption leaves a durable journal at "+phase);Backup.recover(crash);check(!Backup.journal(crash).getBaseFile().exists()&&new Store(crash).all().size()==(phase.equals("after-publish")?4:0),"restart recovery chooses complete commit or rollback at "+phase);plan.close();File retried=Backup.export(crash);check(retried.isFile(),"export still works after recovering an interrupted restore "+phase);Backup.remove(retried.getParentFile());}
        for(int id=4;id<7;id++){Typeface face=Renderer.font(target,id);Paint paint=new Paint(3);paint.setTypeface(face);paint.setTextSize(24);check(face!=Typeface.DEFAULT&&"今天也要好好生活0123456789，。！？".codePoints().allMatch(cp->paint.hasGlyph(new String(Character.toChars(cp)))),"bundled font loads and covers Chinese, digits and punctuation "+Card.FONTS[id]);check(paint.measureText("𠮷☁️")>0,"missing glyph sequence has a non-crashing fallback path "+id);}
        check(Renderer.font(target,999)==Typeface.DEFAULT,"unknown font ID safely falls back to system");Backup.remove(archive.getParentFile());Backup.remove(exportedAgain.getParentFile());
    }
    static class SimulatedCrash extends Error {}
    @Override public void onStart(){Bundle result=new Bundle();target=getTargetContext();try{
        String phase=args.getString("phase","");if(phase.equals("crash-before")){Isolated source=new Isolated(target);fixture(source);File archive=Backup.export(source);Backup.Plan plan=Backup.prepare(target,new FileInputStream(archive));Backup.apply(target,plan,at->{if(at.equals("after-file"))android.os.Process.killProcess(android.os.Process.myPid());});throw new AssertionError("crash injection did not terminate process");}
        else if(phase.equals("sample")){Isolated source=new Isolated(target);fixture(source);File archive=Backup.export(source);File sample=new File(target.getFilesDir(),"review033/qa-complete-roundtrip.zip");Backup.write(sample,Backup.bytes(archive,Backup.MAX_TOTAL));Backup.remove(archive.getParentFile());check(sample.isFile(),"saved isolated complete backup sample for inspection");}
        else if(phase.equals("recover-real")){check(!Backup.journal(target).getBaseFile().exists(),"Application startup recovers a real killed restore process");for(Card card:new Store(target).all())check(!card.id.startsWith("fixture-"),"killed unpublished fixture is not visible as a card "+card.id);}
        else tests();result.putString("stream",report+"Checks passed this run: "+count+"\n");finish(Activity.RESULT_OK,result);
    }catch(Throwable error){result.putString("stream",report+"FAIL "+android.util.Log.getStackTraceString(error));finish(Activity.RESULT_CANCELED,result);}}
}
